use infinite_core::*;use std::num::NonZeroU32;
#[test]
fn unchanged_selection_still_refreshes_definitions_full_reset_and_failed_legacy_attempts(){
 let mut w=World::default();let a=w.spawn(pos()).unwrap();w.define_public_component(1,b"a").unwrap();w.set_component(a,row(ComponentKind::Appearance,ComponentScope::Nearby,1)).unwrap();let mut f=ComponentFrame::new(n(16));capture(&mut w,&mut f);
 let mut sender=ComponentSender::new_with_definitions(12,None);let mut client=ComponentReplica::new_with_definitions(12);let ack=client.apply(sender.prepare(&f,view()).unwrap().unwrap()).unwrap().acknowledgement();sender.acknowledge_packet(&ack).unwrap();capture(&mut w,&mut f);assert!(sender.prepare(&f,view()).unwrap().is_none());
 w.define_public_component(1,b"b").unwrap();capture(&mut w,&mut f);let bytes=sender.prepare(&f,view()).unwrap().unwrap();assert_eq!(u16::from_le_bytes(bytes[36..38].try_into().unwrap()),0);let ack=client.apply(bytes).unwrap().acknowledgement();sender.acknowledge_packet(&ack).unwrap();assert_eq!(client.definition(1).unwrap().revision,2);
 sender.request_full();let packet=sender.prepare(&f,view()).unwrap().unwrap();assert_eq!(packet[3],1);let mut fresh=ComponentReplica::new_with_definitions(12);fresh.apply(packet).unwrap();assert_eq!(fresh.states(),client.states());assert_eq!(fresh.definition(1).unwrap().bytes.as_ref(),b"b");
 let mut legacy=ComponentSender::new(13,None);for _ in 0..3{assert_eq!(legacy.prepare(&f,view()),Err(ComponentError::UnsupportedReferences));assert!(legacy.pending_packet().is_none());}
}
fn n(v:u32)->NonZeroU32{NonZeroU32::new(v).unwrap()}
fn pos()->GridPosition{GridPosition{x:0,y:0}}
fn view()->ViewRect{ViewRect{min:GridPosition{x:-1,y:-1},max:GridPosition{x:1,y:1}}}
fn row(kind:ComponentKind,scope:ComponentScope,id:u32)->ComponentRecord{let mut fields=ComponentFields::default();fields.set_reference(0,id).unwrap();ComponentRecord{key:ComponentKey{kind,instance:0},scope,fields}}
fn capture(w:&mut World,f:&mut ComponentFrame){w.advance_tick().unwrap();f.capture(w).unwrap();}
#[test]
fn definition_admission_reference_counts_replacement_and_generation_cleanup(){
 let mut w=World::default();let a=w.spawn(pos()).unwrap();let r=row(ComponentKind::Appearance,ComponentScope::Nearby,7);
 assert_eq!(w.set_component(a,r),Err(ComponentError::MissingDefinition));assert_eq!(w.component_count(),0);w.define_public_component(7,b"model-7").unwrap();assert!(!w.define_public_component(7,b"model-7").unwrap());w.set_component(a,r).unwrap();assert_eq!(w.remove_public_component_definition(7),Err(ComponentError::DefinitionInUse));
 let mut invalid=r;invalid.fields.set_reference(1,8).unwrap();assert_eq!(w.replace_component_kind(a,ComponentKind::Appearance,&[invalid]),Err(ComponentError::MissingDefinition));assert_eq!(w.components(a).unwrap(),&[r]);assert_eq!(w.remove_public_component_definition(7),Err(ComponentError::DefinitionInUse));
 w.define_public_component(8,b"model-8").unwrap();w.replace_component_kind(a,ComponentKind::Appearance,&[invalid]).unwrap();w.despawn(a).unwrap();assert!(w.remove_public_component_definition(7).unwrap());assert!(w.remove_public_component_definition(8).unwrap());w.define_public_component(7,b"new-model-7").unwrap();assert_eq!(w.public_component_definition(7).unwrap().revision,2);
}
#[test]
fn only_visible_referenced_definitions_are_sent_and_shared_ids_are_deduplicated(){
 let mut w=World::default();let owner=w.spawn(pos()).unwrap();let other=w.spawn(pos()).unwrap();for(id,data)in[(1,b"model".as_slice()),(2,b"private-skill".as_slice()),(3,b"unused".as_slice())]{w.define_public_component(id,data).unwrap();}w.set_component(owner,row(ComponentKind::Appearance,ComponentScope::Nearby,1)).unwrap();w.set_component(other,row(ComponentKind::Appearance,ComponentScope::Nearby,1)).unwrap();w.set_component(owner,row(ComponentKind::Skill,ComponentScope::Owner,2)).unwrap();let mut f=ComponentFrame::new(n(16));capture(&mut w,&mut f);
 let mut sender=ComponentSender::new_with_definitions(1,Some(other));let mut client=ComponentReplica::new_with_definitions(1);let bytes=sender.prepare(&f,view()).unwrap().unwrap();assert_eq!(u16::from_le_bytes(bytes[38..40].try_into().unwrap()),1);client.apply(bytes).unwrap();assert_eq!(client.definition_count(),1);assert_eq!(client.definition(1).unwrap().bytes.as_ref(),b"model");assert!(client.definition(2).is_none());assert!(client.definition(3).is_none());
 let mut owner_sender=ComponentSender::new_with_definitions(2,Some(owner));let mut owner_client=ComponentReplica::new_with_definitions(2);owner_client.apply(owner_sender.prepare(&f,view()).unwrap().unwrap()).unwrap();assert_eq!(owner_client.definition_count(),2);
 let mut v1=ComponentSender::new(3,Some(owner));assert_eq!(v1.prepare(&f,view()),Err(ComponentError::UnsupportedReferences));assert!(v1.pending_packet().is_none());
}
#[test]
fn definition_only_changes_wait_for_ack_and_do_not_rewrite_inflight_bytes(){
 let mut w=World::default();let e=w.spawn(pos()).unwrap();w.define_public_component(1,b"old").unwrap();w.set_component(e,row(ComponentKind::Appearance,ComponentScope::Nearby,1)).unwrap();let mut f=ComponentFrame::new(n(16));capture(&mut w,&mut f);let mut sender=ComponentSender::new_with_definitions(9,None);let mut client=ComponentReplica::new_with_definitions(9);let old=sender.prepare(&f,view()).unwrap().unwrap().to_vec();let ack=client.apply(&old).unwrap().acknowledgement();w.define_public_component(1,b"new").unwrap();capture(&mut w,&mut f);assert_eq!(sender.pending_packet(),Some(old.as_slice()));assert!(client.apply(&old).unwrap().duplicate);assert_eq!(client.definition(1).unwrap().bytes.as_ref(),b"old");let mut wrong=ack;wrong[2]=1;assert!(sender.acknowledge_packet(&wrong).is_err());sender.acknowledge_packet(&ack).unwrap();let update=sender.prepare(&f,view()).unwrap().unwrap().to_vec();assert_eq!(u16::from_le_bytes(update[36..38].try_into().unwrap()),0);assert_eq!(u16::from_le_bytes(update[38..40].try_into().unwrap()),1);let ack=client.apply(&update).unwrap().acknowledgement();sender.acknowledge_packet(&ack).unwrap();assert_eq!(client.definition(1).unwrap().bytes.as_ref(),b"new");assert_eq!(client.definition(1).unwrap().revision,2);assert!(sender.prepare(&f,view()).unwrap().is_none());
}
#[test]
fn same_integer_switching_between_reference_and_scalar_updates_and_releases_cache(){
 let mut w=World::default();let e=w.spawn(pos()).unwrap();w.define_public_component(5,b"asset").unwrap();let mut r=row(ComponentKind::Appearance,ComponentScope::Nearby,5);w.set_component(e,r).unwrap();let mut f=ComponentFrame::new(n(16));let mut sender=ComponentSender::new_with_definitions(2,None);let mut client=ComponentReplica::new_with_definitions(2);
 for stage in 0..3{if stage==1{r.fields.set(0,5).unwrap();}else{r.fields.set_reference(0,5).unwrap();}w.set_component(e,r).unwrap();capture(&mut w,&mut f);let ack=client.apply(sender.prepare(&f,view()).unwrap().unwrap()).unwrap().acknowledgement();sender.acknowledge_packet(&ack).unwrap();assert_eq!(client.states()[0].record,r);assert_eq!(client.definition_count(),usize::from(stage!=1));}
 w.remove_component(e,r.key).unwrap();w.remove_public_component_definition(5).unwrap();capture(&mut w,&mut f);let ack=client.apply(sender.prepare(&f,view()).unwrap().unwrap()).unwrap().acknowledgement();sender.acknowledge_packet(&ack).unwrap();assert!(client.states().is_empty());assert_eq!(client.definition_count(),0);
}
#[test]
fn missing_definition_and_truncated_catalog_leave_both_replica_tables_unchanged(){
 let mut w=World::default();let e=w.spawn(pos()).unwrap();let r=ComponentRecord{key:ComponentKey{kind:ComponentKind::Appearance,instance:0},scope:ComponentScope::Nearby,fields:ComponentFields::from_words(&[1]).unwrap()};w.set_component(e,r).unwrap();let mut f=ComponentFrame::new(n(16));capture(&mut w,&mut f);let mut sender=ComponentSender::new_with_definitions(1,None);let mut client=ComponentReplica::new_with_definitions(1);let mut malformed=sender.prepare(&f,view()).unwrap().unwrap().to_vec();malformed[50..52].copy_from_slice(&1u16.to_le_bytes());assert_eq!(client.apply(&malformed),Err(ComponentError::MissingDefinition));assert!(client.states().is_empty());assert_eq!(client.definition_count(),0);
 let ack=client.apply(sender.pending_packet().unwrap()).unwrap().acknowledgement();sender.acknowledge_packet(&ack).unwrap();w.define_public_component(1,b"public data").unwrap();w.set_component(e,row(ComponentKind::Appearance,ComponentScope::Nearby,1)).unwrap();capture(&mut w,&mut f);let packet=sender.prepare(&f,view()).unwrap().unwrap().to_vec();let before=client.states().to_vec();for end in 0..packet.len(){assert!(client.apply(&packet[..end]).is_err());assert_eq!(client.states(),before);assert_eq!(client.definition_count(),0);}client.apply(&packet).unwrap();assert_eq!(client.definition_count(),1);
}
#[test]
fn full_recovery_resends_needed_definitions_and_catalog_capacity_is_bounded(){
 let mut w=World::default();for id in 0..MAX_STATIC_DEFINITIONS as u32{w.define_public_component(id,b"x").unwrap();}assert_eq!(w.define_public_component(MAX_STATIC_DEFINITIONS as u32,b"extra"),Err(ComponentError::DefinitionLimit));assert_eq!(w.define_public_component(0,&vec![0;MAX_STATIC_DEFINITION_BYTES+1]),Err(ComponentError::DefinitionLimit));
 for base in (0..MAX_STATIC_DEFINITIONS).step_by(COMPONENT_FIELDS){let e=w.spawn(pos()).unwrap();let mut fields=ComponentFields::default();for i in 0..COMPONENT_FIELDS{fields.set_reference(i,(base+i)as u32).unwrap();}w.set_component(e,ComponentRecord{key:ComponentKey{kind:ComponentKind::GroundItem,instance:0},scope:ComponentScope::Map,fields}).unwrap();}
 let mut f=ComponentFrame::new(n(16));capture(&mut w,&mut f);let mut sender=ComponentSender::new_with_definitions(5,None);let mut client=ComponentReplica::new_with_definitions(5);let ack=client.apply(sender.prepare(&f,view()).unwrap().unwrap()).unwrap().acknowledgement();sender.acknowledge_packet(&ack).unwrap();assert_eq!(client.definition_count(),MAX_STATIC_DEFINITIONS);sender.request_full();let packet=sender.prepare(&f,view()).unwrap().unwrap();assert_eq!(u16::from_le_bytes(packet[38..40].try_into().unwrap())as usize,MAX_STATIC_DEFINITIONS);let mut fresh=ComponentReplica::new_with_definitions(5);fresh.apply(packet).unwrap();assert_eq!(fresh.states(),client.states());assert_eq!(fresh.definition_count(),MAX_STATIC_DEFINITIONS);
}
